insert into public.berita(judul,slug,kategori,ringkasan,isi,status,tanggal_terbit) values('Selamat Datang di Portal PMI Kota Bengkulu','selamat-datang-portal-pmi-kota-bengkulu','Pengumuman','Portal informasi PMI Kota Bengkulu mulai dikembangkan.','Konten awal untuk memastikan koneksi Supabase berfungsi.','terbit',now()) on conflict(slug) do nothing;
insert into public.agenda(judul,lokasi,deskripsi,mulai_pada,status) select 'Pelatihan Dasar Relawan','Markas PMI Kota Bengkulu','Contoh agenda awal.',now()+interval '14 days','terjadwal' where not exists(select 1 from public.agenda where judul='Pelatihan Dasar Relawan');